import type { ReactNode } from 'react';

export function InsuranceHeadingDataRow({ label, value }: { label: string; value: ReactNode }) {
    return (
        <div className="flex flex-row items-stretch border-b border-b-white-blue-500 last:border-b-0">
            <p className="min-w-[140px] shrink-0 bg-white-blue-100 px-4 py-3 text-sm text-primery-blue-500 font-semibold tracking-normal leading-6">
                {label}
            </p>
            <p className="flex flex-1 items-center gap-4 px-4 py-3 text-primery-blue-900 text-base font-medium break-words">
                {value}
            </p>
        </div>
    );
}
